// Admin panel (generated by `lila admin --react`): dashboard + CRUD for every
// model passed to Admin(models=[...], react=True). Edit freely.
import { useState, type ReactElement, type ReactNode } from "react";
import { Link } from "@lila";
import {
  Badge, Button, Card, Checkbox, DataTable, Form, Input, Modal, ProgressBar, Select, SubmitButton,
  ThemeToggle, Toaster,
} from "../../components/ui";

interface Field {
  name: string;
  input_type: "text" | "number" | "password" | "active_select" | "boolean_select" | "datetime-local" | "date";
  required: boolean;
  nullable: boolean;
  has_default: boolean;
}

interface ModelSpec {
  name: string;
  plural: string;
  api: string;
  headers: string[];
  fields: Field[];
}

interface LogFile {
  date: string;
  file: string;
  lines: string[];
}

interface PanelProps {
  prefix: string;
  models: Array<{ name: string; plural: string }>;
  admin: { username: string };
  view: "dashboard" | "model";
  metrics?: Record<string, any>;
  logs?: LogFile[];
  model?: ModelSpec;
}

type Row = Record<string, any>;

export default function AdminPanel(props: PanelProps) {
  const { prefix, models, admin, view } = props;
  return (
    <div className="flex min-h-screen flex-col">
      <ProgressBar />
      <header className="sticky top-0 z-40 border-b border-border bg-surface dark:bg-surface-dark">
        <div className="mx-auto flex max-w-7xl items-center justify-between gap-3 px-4 py-3">
          <Link href={prefix} className="bg-gradient-to-r from-lila-800 via-lila-700 to-lila-500 dark:from-[#e5c2ff] dark:via-lila-300 dark:to-indigo-400 bg-clip-text text-xl font-black text-transparent">
            Lila Admin
          </Link>
          <div className="flex items-center gap-2">
            <Badge tone="primary" soft>{admin.username}</Badge>
            <ThemeToggle />
            {/* Full navigation: the server clears the admin session. */}
            <a href={`${prefix}/logout`} className="btn-outline btn-sm">Log out</a>
          </div>
        </div>
      </header>
      <div className="mx-auto grid w-full max-w-7xl flex-1 grid-cols-1 gap-6 px-4 py-6 md:grid-cols-[14rem_1fr]">
        <aside className="card flex h-fit flex-col gap-1 p-3">
          <Link href={prefix} exact className="nav-link">📊 Dashboard</Link>
          <h2 className="field-label mt-3 px-3">Models</h2>
          {models.map((m) => (
            <Link key={m.plural} href={`${prefix}/${m.plural}`} className="nav-link">🗂️ {m.name}</Link>
          ))}
        </aside>
        <main className="min-w-0 space-y-6">
          {view === "dashboard" ? <Dashboard {...props} /> : props.model ? <ModelPage model={props.model} /> : null}
        </main>
      </div>
      <Toaster />
    </div>
  );
}

function Stat({ label, value }: { label: string; value: ReactNode }) {
  return (
    <div className="card p-4">
      <p className="field-label">{label}</p>
      <p className="mt-1 text-2xl font-black">{value}</p>
    </div>
  );
}

function Dashboard({ prefix, metrics = {}, logs = [] }: PanelProps) {
  const cache = metrics.cache || {};
  return (
    <>
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        <Stat label="Process RAM" value={`${metrics.process_ram_mb ?? "-"} MB`} />
        <Stat label="CPU" value={`${metrics.cpu_percent ?? "-"} %`} />
        <Stat label="System RAM" value={`${metrics.system_ram_percent ?? "-"} %`} />
        <Stat label="Threads" value={metrics.threads ?? "-"} />
      </div>
      <Card
        title="Cache"
        description={`${cache.active_backend || cache.driver || "memory"} · ${cache.memory_items ?? 0} items · ${cache.memory_mb ?? 0} / ${cache.max_mb ?? "-"} MB`}
        actions={
          <Button size="sm" variant="outline" url={`${prefix}/cache/clear`} method="POST" confirm="Clear the cache? Sessions are kept." successMessage>
            Clear cache
          </Button>
        }
      />
      <Card
        title="Logs"
        description={logs.length ? `${logs.length} file(s)` : "No logs yet"}
        actions={
          logs.length ? (
            <Button size="sm" variant="danger" url={`${prefix}/logs`} method="DELETE" confirm="Delete every log file?" successMessage>
              Clear logs
            </Button>
          ) : null
        }
      >
        <div className="space-y-4">
          {logs.map((log) => (
            <details key={`${log.date}/${log.file}`} className="rounded-xl border border-border">
              <summary className="cursor-pointer px-4 py-2 text-sm font-semibold">{log.date} / {log.file}</summary>
              <pre className="max-h-80 overflow-auto px-4 py-2 text-xs">{log.lines.join("\n")}</pre>
            </details>
          ))}
        </div>
      </Card>
    </>
  );
}

function fieldLabel(name: string) {
  return name.replace(/_/g, " ").replace(/^\w/, (c) => c.toUpperCase());
}

function initialValues(fields: Field[], row: Row | null): Record<string, any> {
  const values: Record<string, any> = {};
  for (const field of fields) {
    const value = row ? row[field.name] : undefined;
    if (field.input_type === "password") values[field.name] = "";
    else if (field.input_type === "active_select") values[field.name] = value === undefined || value === null ? "1" : String(Number(value));
    else if (field.input_type === "boolean_select") values[field.name] = Boolean(value);
    else if (field.input_type === "datetime-local" && value) values[field.name] = String(value).slice(0, 16);
    else values[field.name] = value === undefined || value === null ? "" : String(value);
  }
  return values;
}

function FieldInput({ field, editing }: { field: Field; editing: boolean }) {
  const label = fieldLabel(field.name);
  const required = field.required && !(editing && field.input_type === "password");
  switch (field.input_type) {
    case "active_select":
      return <Select name={field.name} label={label} options={[{ value: "1", label: "Active" }, { value: "0", label: "Inactive" }]} />;
    case "boolean_select":
      return <Checkbox name={field.name} label={label} />;
    case "password":
      return <Input name={field.name} type="password" label={label} required={required} autoComplete="new-password"
        hint={editing ? "Leave empty to keep the current password" : undefined} />;
    default:
      return <Input name={field.name} type={field.input_type} step={field.input_type === "number" ? "any" : undefined} label={label} required={required} />;
  }
}

function ModelPage({ model }: { model: ModelSpec }) {
  const [editing, setEditing] = useState<Row | null>(null);
  const [open, setOpen] = useState(false);
  const [refresh, setRefresh] = useState(0);
  const openForm = (row: Row | null) => {
    setEditing(row);
    setOpen(true);
  };
  const booleans = new Set(model.fields.filter((f) => f.input_type === "boolean_select").map((f) => f.name));
  const columns = model.headers.map((key) => ({
    key,
    label: fieldLabel(key),
    sortable: true,
    render:
      key === "active"
        ? (row: Row) => (Number(row.active) ? <Badge tone="success" soft>active</Badge> : <Badge tone="danger" soft>inactive</Badge>)
        : booleans.has(key)
          ? (row: Row) => (row[key] ? <Badge tone="primary" soft>✓</Badge> : <span className="text-muted-foreground">—</span>)
          : undefined,
  }));
  return (
    <>
      <div className="flex items-center justify-between gap-4">
        <h1 className="text-2xl font-black">{model.name}</h1>
        <div className="flex gap-2">
          <a className="btn-outline btn-sm" href={`${model.api}/export`}>Export CSV</a>
          <Button size="sm" onClick={() => openForm(null)}>+ New</Button>
        </div>
      </div>
      <DataTable<Row>
        key={model.api}
        url={model.api}
        refreshKey={refresh}
        defaultSort={{ key: model.headers.includes("id") ? "id" : model.headers[0], desc: true }}
        columns={columns}
        onEdit={(row) => openForm(row)}
        onDelete={`${model.api}/:id`}
      />
      <Modal open={open} onClose={() => setOpen(false)} size="lg" title={editing ? `Edit ${model.name} #${editing.id}` : `New ${model.name}`}>
        <Form
          key={editing ? `${model.api}/${editing.id}` : `${model.api}/new`}
          action={editing ? `${model.api}/${editing.id}` : model.api}
          method={editing ? "PUT" : "POST"}
          initial={initialValues(model.fields, editing)}
          successToast="Saved"
          className="grid gap-4 md:grid-cols-2"
          onSuccess={() => {
            setOpen(false);
            setRefresh((n) => n + 1);
          }}
        >
          {model.fields.map((field) => <FieldInput key={field.name} field={field} editing={Boolean(editing)} />)}
          <div className="md:col-span-2"><SubmitButton>Save</SubmitButton></div>
        </Form>
      </Modal>
    </>
  );
}

AdminPanel.layout = (page: ReactElement) => page;
